import { eq } from 'drizzle-orm';
import { db } from './db';
import { authors } from './db/schema';

export function getAuthor(id: number) {
  return db.select().from(authors).where(eq(authors.id, id));
}
import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

export function listPosts() {
  return prisma.post.findMany({ orderBy: { createdAt: 'desc' } });
}
import { pgTable, serial, text } from 'drizzle-orm/pg-core';

export const authors = pgTable('authors', {
  id: serial('id').primaryKey(),
  name: text('name').notNull(),
  email: text('email').notNull().unique()
});
import { drizzle } from 'drizzle-orm/postgres-js';
import postgres from 'postgres';
import * as schema from './schema';

export const db = drizzle(postgres(process.env.DATABASE_URL ?? 'postgres://localhost/blog'), { schema });
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model Post {
  id        Int      @id @default(autoincrement())
  title     String
  body      String
  createdAt DateTime @default(now())
}
{ "compilerOptions": { "target": "ES2022", "module": "ESNext", "moduleResolution": "bundler", "strict": true, "skipLibCheck": true, "noEmit": true }, "include": ["src"] }

